INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5060692, 738609, 14855, '<td valign="top">Great shot.  I feel like this captures the essence of the challenge.</td>', 'Great shot.  I feel like this captures the essence of the challenge.', '2008-11-12 18:46:00.000000', NULL, 1),
(5060744, 738465, 98141, '<td valign="top">I like how clear the person in the light is. I wish the pole and the girl were not so close to the edge.</td>', 'I like how clear the person in the light is. I wish the pole and the girl were not so close to the edge.', '2008-11-12 19:16:33.000000', NULL, 1),
(5060745, 737853, 98141, '<td valign="top">Hahaha, I like this, nice composition.</td>', 'Hahaha, I like this, nice composition.', '2008-11-12 19:16:51.000000', NULL, 1),
(5060748, 738141, 98141, '<td valign="top">This feels like a picture of a picture, would prefer it without the black edges and the tilt. I think the composition would have been nice if it were more "normal."</td>', 'This feels like a picture of a picture, would prefer it without the black edges and the tilt. I think the composition would have been nice if it were more "normal."', '2008-11-12 19:18:28.000000', NULL, 1),
(5060750, 737363, 98141, '<td valign="top">Feels oversharpened or something, looks too rough.</td>', 'Feels oversharpened or something, looks too rough.', '2008-11-12 19:19:10.000000', NULL, 1),
(5060751, 738662, 98141, '<td valign="top">Would like the surface to be plainer and the colors to be more saturated.</td>', 'Would like the surface to be plainer and the colors to be more saturated.', '2008-11-12 19:19:57.000000', NULL, 1),
(5060753, 738268, 98141, '<td valign="top">What a handsome dog! I love dogs. I think it''s nicely composed and I like the colors.</td>', 'What a handsome dog! I love dogs. I think it''s nicely composed and I like the colors.', '2008-11-12 19:20:34.000000', NULL, 1),
(5060754, 738398, 98141, '<td valign="top">Nice abstract, I like all the shadows.</td>', 'Nice abstract, I like all the shadows.', '2008-11-12 19:20:48.000000', NULL, 1),
(5060757, 738115, 98141, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2008-11-12 19:22:23.000000', NULL, 1),
