(5060760, 737718, 98141, '<td valign="top">Nice detail, very visually interesting and nice contrast with the background.</td>', 'Nice detail, very visually interesting and nice contrast with the background.', '2008-11-12 19:23:09.000000', NULL, 1),
(5060764, 737027, 98141, '<td valign="top">Not as exciting as some of the other leaf shots I''ve seen in this challenge, but nothing very bad about it. Would like the main leaf to be off center. It''s simple and nothing pops though.</td>', 'Not as exciting as some of the other leaf shots I''ve seen in this challenge, but nothing very bad about it. Would like the main leaf to be off center. It''s simple and nothing pops though.', '2008-11-12 19:24:40.000000', NULL, 1),
(5060767, 738273, 99411, '<td valign="top">Gets a 10 from me. Great idea, well executed and fit the challenge perfectly.</td>', 'Gets a 10 from me. Great idea, well executed and fit the challenge perfectly.', '2008-11-12 19:26:19.000000', NULL, 1),
(5060769, 738596, 98141, '<td valign="top">I like the colors in this. Would like the main leaf to be a little more off-center.</td>', 'I like the colors in this. Would like the main leaf to be a little more off-center.', '2008-11-12 19:26:42.000000', NULL, 1),
