(5062830, 738108, 66616, '<td valign="top">great shot</td>', 'great shot', '2008-11-13 20:50:48.000000', NULL, 1),
(5062834, 738106, 96881, '<td valign="top">Firstly, would not have added the extra (actually it was rose) to the title, it detracts from anything your title is trying to achieve.<br/> <br/>Ignoring that (as I don''t vote on titles anyway)<br/>I like what you are trying to achieve here  The top of the bottle needed a litte more light from the front/right so it didn''t get lost.  I like to composition and simple border.</td>', 'Firstly, would not have added the extra (actually it was rose) to the title, it detracts from anything your title is trying to achieve. Ignoring that (as I don''t vote on titles anyway)I like what you are trying to achieve here  The top of the bottle needed a litte more light from the front/right so it didn''t get lost.  I like to composition and simple border.', '2008-11-13 20:52:01.000000', NULL, 1),
(5062839, 738305, 66616, '<td valign="top">perhaps closer cropping would have made this a better image</td>', 'perhaps closer cropping would have made this a better image', '2008-11-13 20:53:02.000000', NULL, 1),
(5062842, 736924, 96881, '<td valign="top">Simple, yet Great.  Works well here.  Only issue is that some parts appear to not be sharp in the leaf.</td>', 'Simple, yet Great.  Works well here.  Only issue is that some parts appear to not be sharp in the leaf.', '2008-11-13 20:53:54.000000', NULL, 1),
