INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5062879, 738541, 66616, '<td valign="top">would be better if it was in focus</td>', 'would be better if it was in focus', '2008-11-13 21:12:00.000000', NULL, 1),
(5062889, 738188, 66616, '<td valign="top">I think the pattern spoils this image.</td>', 'I think the pattern spoils this image.', '2008-11-13 21:18:16.000000', NULL, 1),
(5062890, 738362, 66616, '<td valign="top">great shot</td>', 'great shot', '2008-11-13 21:18:34.000000', NULL, 1),
(5062921, 737551, 77196, '<td valign="top">IMO this wants to be cropped tighter. There is a lot going on in the shot, and no real focal point. Also, the rotting apple/pear in the upper right is less than appealing.</td>', 'IMO this wants to be cropped tighter. There is a lot going on in the shot, and no real focal point. Also, the rotting apple/pear in the upper right is less than appealing.', '2008-11-13 22:15:48.000000', NULL, 1),
(5062928, 738096, 77196, '<td valign="top">Something''s off in your colors - the tomatoes look more orange than red.</td>', 'Something''s off in your colors - the tomatoes look more orange than red.', '2008-11-13 22:20:28.000000', NULL, 1),
(5062930, 738660, 77196, '<td valign="top">Gotta choose - red hydrant or red building. Your two focal points are in conflict and too far apart. Either would have made a good shot, but here, I just feel light they''re fighting for attention.</td>', 'Gotta choose - red hydrant or red building. Your two focal points are in conflict and too far apart. Either would have made a good shot, but here, I just feel light they''re fighting for attention.', '2008-11-13 22:21:39.000000', NULL, 1),
(5062932, 738483, 77196, '<td valign="top">I want to like this, but orange light trails with deep red? Plus, your flash umbrella is clearly reflected in the bottle. The light umbrella may be excusable, but the clashing colors just completely defuse the mood of the dark red &amp; wine, which is so nice.</td>', 'I want to like this, but orange light trails with deep red? Plus, your flash umbrella is clearly reflected in the bottle. The light umbrella may be excusable, but the clashing colors just completely defuse the mood of the dark red & wine, which is so nice.', '2008-11-13 22:24:20.000000', NULL, 1),
(5062944, 738651, 77196, '<td valign="top">No no no! This grinds on my nerves. You''ve mixed a blue based red (candy dish) with an orange based red, and they clash. I like the idea of the lone green M&amp;M (unless of course, you''re red/green color blind, in which case I give you kudos for even attempting this shot). Your focus, crop, composition, and lighting are nice. The table top (surface) is a bit busy for the simple lines of the dish.</td>', 'No no no! This grinds on my nerves. You''ve mixed a blue based red (candy dish) with an orange based red, and they clash. I like the idea of the lone green M&M (unless of course, you''re red/green color blind, in which case I give you kudos for even attempting this shot). Your focus, crop, composition, and lighting are nice. The table top (surface) is a bit busy for the simple lines of the dish.', '2008-11-13 22:35:14.000000', NULL, 1),
(5062947, 737980, 77196, '<td valign="top">If this is your reject for the Hearts challenge, I''d love to see your entry. This is very nice. The black mesh helps add some definition and interest. The hearts in the water drops are near perfect, and the lighting highlights very acceptable. The solid red background provides a solid foundation. Shot goes a bit OOF in bottom 1/3, but the rest of the shot more than makes up for it.</td>', 'If this is your reject for the Hearts challenge, I''d love to see your entry. This is very nice. The black mesh helps add some definition and interest. The hearts in the water drops are near perfect, and the lighting highlights very acceptable. The solid red background provides a solid foundation. Shot goes a bit OOF in bottom 1/3, but the rest of the shot more than makes up for it.', '2008-11-13 22:38:27.000000', NULL, 1),
(5062949, 738131, 77196, '<td valign="top">Absolutely perfect expression, and the placement of the roses is perfect. This picture invites me to experience it with her, and I feel like she''s just sniffed the roses and is thinking about the person who gave them to her, and why. The expression says the roses were a bit unexpected, thought-provoking, yet cherished. This could be a very sad picture - like roses "from" grandma just before her funeral. Or it could be an ordinary day with roses from Daddy just to brighten her day or to celebrate something she did right, but that doesn''t necessarily feel good. If she were my daughter, this shot would have a place on my fireplace mantle long after she was grown and had left the house. It would be a picture to show to her children and tell the story of when mommy was a little girl.</td>', 'Absolutely perfect expression, and the placement of the roses is perfect. This picture invites me to experience it with her, and I feel like she''s just sniffed the roses and is thinking about the person who gave them to her, and why. The expression says the roses were a bit unexpected, thought-provoking, yet cherished. This could be a very sad picture - like roses "from" grandma just before her funeral. Or it could be an ordinary day with roses from Daddy just to brighten her day or to celebrate something she did right, but that doesn''t necessarily feel good. If she were my daughter, this shot would have a place on my fireplace mantle long after she was grown and had left the house. It would be a picture to show to her children and tell the story of when mommy was a little girl.', '2008-11-13 22:43:45.000000', NULL, 1),
(5062950, 738074, 58457, '<td valign="top">this is one of my favorites in the challenge.  so simple.  I like minimalism, and this one fits the theme great!</td>', 'this is one of my favorites in the challenge.  so simple.  I like minimalism, and this one fits the theme great!', '2008-11-13 22:44:24.000000', NULL, 1),
(5062953, 737623, 77196, '<td valign="top">Her frowny brows contradict the picture. Flower may be too close to her nose too.</td>', 'Her frowny brows contradict the picture. Flower may be too close to her nose too.', '2008-11-13 22:50:07.000000', NULL, 1),
