INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5065240, 738143, 97893, '<td valign="top">Nice pepper! Nice shot!</td>', 'Nice pepper! Nice shot!', '2008-11-15 14:18:50.000000', NULL, 1),
(5065281, 738510, 54478, '<td valign="top">Good photo, but the image seems to be slightly out of focus.</td>', 'Good photo, but the image seems to be slightly out of focus.', '2008-11-15 15:24:26.000000', NULL, 1),
(5065283, 738638, 54478, '<td valign="top">The photo seems a little dark on the left side of the apple and a little out of focus.</td>', 'The photo seems a little dark on the left side of the apple and a little out of focus.', '2008-11-15 15:24:57.000000', NULL, 1),
(5065284, 738273, 54478, '<td valign="top">Beautiful. Great capture and I love how the clouds are infront of the sun. The larger border on the bottom is a tad distracting.</td>', 'Beautiful. Great capture and I love how the clouds are infront of the sun. The larger border on the bottom is a tad distracting.', '2008-11-15 15:27:33.000000', NULL, 1),
(5065285, 738389, 54478, '<td valign="top">Awesome use of texture and nice high speed catch. The photo is a little grainy, but I am willing to bet you had to up the ISO to get the shutter speed high enough. Good catch.</td>', 'Awesome use of texture and nice high speed catch. The photo is a little grainy, but I am willing to bet you had to up the ISO to get the shutter speed high enough. Good catch.', '2008-11-15 15:28:16.000000', NULL, 1),
(5065286, 736959, 54478, '<td valign="top">The photo seems to the the focal point of this photo. I wish I could have seen all of the tree instead of the lower portion. The person in the door way is also distracting. Would have been even better if the ground would have more uniformly wet.</td>', 'The photo seems to the the focal point of this photo. I wish I could have seen all of the tree instead of the lower portion. The person in the door way is also distracting. Would have been even better if the ground would have more uniformly wet.', '2008-11-15 15:30:11.000000', NULL, 1),
(5065287, 736885, 54478, '<td valign="top">Interesting photo. Good use of the color red, but the lake is distracting and the photo isn''t level which gives it a lop sidded feeling.</td>', 'Interesting photo. Good use of the color red, but the lake is distracting and the photo isn''t level which gives it a lop sidded feeling.', '2008-11-15 15:30:58.000000', NULL, 1),
(5065288, 738249, 54478, '<td valign="top">I find the subject just a tad boring. Nice composition though.</td>', 'I find the subject just a tad boring. Nice composition though.', '2008-11-15 15:31:35.000000', NULL, 1),
(5065290, 738362, 54478, '<td valign="top">Nice use of the color red, but the blue tint to the green leaves and sticks seem unnatural and distracting.</td>', 'Nice use of the color red, but the blue tint to the green leaves and sticks seem unnatural and distracting.', '2008-11-15 15:32:21.000000', NULL, 1),
(5065292, 736924, 54478, '<td valign="top">Nice use of the color red, but the red leaf in the center of the field of view is a tad boring. Would have been nice if the photo was wider and the leaf was off to one side, to utilize the rule of thirds, against a plain blue sky.</td>', 'Nice use of the color red, but the red leaf in the center of the field of view is a tad boring. Would have been nice if the photo was wider and the leaf was off to one side, to utilize the rule of thirds, against a plain blue sky.', '2008-11-15 15:33:33.000000', NULL, 1),
(5065294, 738268, 54478, '<td valign="top">Nice composition. Using the flash seems to have made the dog properly exposed, but it left the back ground under exposed. Beautiful dog.</td>', 'Nice composition. Using the flash seems to have made the dog properly exposed, but it left the back ground under exposed. Beautiful dog.', '2008-11-15 15:34:45.000000', NULL, 1),
(5065295, 738159, 54478, '<td valign="top">This just seems like a photo of an advertisement or billboard.</td>', 'This just seems like a photo of an advertisement or billboard.', '2008-11-15 15:35:27.000000', NULL, 1),
(5065296, 737670, 54478, '<td valign="top">Great use of the color read. Beautiful bird. THe top half of the photo seems to be a tad over exposed while the lower portion seems under exposed.</td>', 'Great use of the color read. Beautiful bird. THe top half of the photo seems to be a tad over exposed while the lower portion seems under exposed.', '2008-11-15 15:36:47.000000', NULL, 1),
(5065298, 737786, 54478, '<td valign="top">Decent photo, well taken, but the subject seems a little boring. A close up of the red wall on the barn would have made a great photo. You could also try taking a photo of the entire wall at an angle and using a shallow DOF.</td>', 'Decent photo, well taken, but the subject seems a little boring. A close up of the red wall on the barn would have made a great photo. You could also try taking a photo of the entire wall at an angle and using a shallow DOF.', '2008-11-15 15:39:07.000000', NULL, 1),
(5065299, 737718, 54478, '<td valign="top">Good photo, but I wish composition was a little different. My eye is drawn to the top right of the photo. I wish the leaf was rotated tad bit with the center of the leaf of centered to the right or left. Beautiful color red.</td>', 'Good photo, but I wish composition was a little different. My eye is drawn to the top right of the photo. I wish the leaf was rotated tad bit with the center of the leaf of centered to the right or left. Beautiful color red.', '2008-11-15 15:40:26.000000', NULL, 1),
(5065300, 738460, 54478, '<td valign="top">Good photo, but I wish I could have seen a little more detail in the reflection of the leaf.</td>', 'Good photo, but I wish I could have seen a little more detail in the reflection of the leaf.', '2008-11-15 15:42:06.000000', NULL, 1),
(5065302, 738543, 54478, '<td valign="top">Awesome use of the color red. I more shallow DOW would have been neat too.</td>', 'Awesome use of the color red. I more shallow DOW would have been neat too.', '2008-11-15 15:43:55.000000', NULL, 1),
(5065304, 738267, 54478, '<td valign="top">Cool high speed shot, but the photo feels a little grainy. I also think I white or no border would have looked better.</td>', 'Cool high speed shot, but the photo feels a little grainy. I also think I white or no border would have looked better.', '2008-11-15 15:45:17.000000', NULL, 1),
(5065306, 738560, 54478, '<td valign="top">Good use of the color red. I am not sure how this photo makes me feel.</td>', 'Good use of the color red. I am not sure how this photo makes me feel.', '2008-11-15 15:46:31.000000', NULL, 1),
(5065307, 738596, 54478, '<td valign="top">I wish the leaf was a tad more off center and red was more prominent in the photo.</td>', 'I wish the leaf was a tad more off center and red was more prominent in the photo.', '2008-11-15 15:48:15.000000', NULL, 1),
(5065308, 738239, 54478, '<td valign="top">Cool use of the color red. Nice DOF</td>', 'Cool use of the color red. Nice DOF', '2008-11-15 15:48:42.000000', NULL, 1),
(5065309, 738356, 54478, '<td valign="top">Good use of the color red, but the photo just seems a tad boring.</td>', 'Good use of the color red, but the photo just seems a tad boring.', '2008-11-15 15:49:10.000000', NULL, 1),
(5065310, 738146, 54478, '<td valign="top">Photo is under exposed and a little out of focus. Would have been a beautiful sunset photo.</td>', 'Photo is under exposed and a little out of focus. Would have been a beautiful sunset photo.', '2008-11-15 15:49:39.000000', NULL, 1),
(5065311, 737940, 54478, '<td valign="top">The compesition doesn''t do a whole lot for me and the photo is a little under exposed. Beautiful fish and the Red Oranda is one of my favorite species of gold fish.</td>', 'The compesition doesn''t do a whole lot for me and the photo is a little under exposed. Beautiful fish and the Red Oranda is one of my favorite species of gold fish.', '2008-11-15 15:51:39.000000', NULL, 1),
(5065313, 738485, 54478, '<td valign="top">Nice ue of the color red, but the shadow just seems a tad distracting for some reason. The border on the top and bottom is a nice touch.</td>', 'Nice ue of the color red, but the shadow just seems a tad distracting for some reason. The border on the top and bottom is a nice touch.', '2008-11-15 15:52:24.000000', NULL, 1),
(5065315, 737835, 54478, '<td valign="top">Nice photo. Awesome use of the color red... nothing says sports car than the color red.</td>', 'Nice photo. Awesome use of the color red... nothing says sports car than the color red.', '2008-11-15 15:56:17.000000', NULL, 1),
(5065317, 737373, 54478, '<td valign="top">Nice use of the color red. I like the use of thirds. The photo almost seems too crisp at the edges.</td>', 'Nice use of the color red. I like the use of thirds. The photo almost seems too crisp at the edges.', '2008-11-15 15:59:55.000000', NULL, 1),
(5065319, 738141, 54478, '<td valign="top">The rotation is distracting. I think leaving the rotation normal and some lighting behind the wine glass would have added some sparkle.</td>', 'The rotation is distracting. I think leaving the rotation normal and some lighting behind the wine glass would have added some sparkle.', '2008-11-15 16:01:03.000000', NULL, 1),
(5065320, 738637, 54478, '<td valign="top">I love the contrast of the red and blue. I wish there was some more texture of the leafe in the center. Good use of contrasting colors.</td>', 'I love the contrast of the red and blue. I wish there was some more texture of the leafe in the center. Good use of contrasting colors.', '2008-11-15 16:01:42.000000', NULL, 1),
(5065332, 737101, 54478, '<td valign="top">I had a hard time determining what this is a photo of. I wish the portion of the flower onthe right would have been more in focus.</td>', 'I had a hard time determining what this is a photo of. I wish the portion of the flower onthe right would have been more in focus.', '2008-11-15 16:04:49.000000', NULL, 1),
(5065336, 738686, 54478, '<td valign="top">Good photo, but the girl on the right is a tad distracting.</td>', 'Good photo, but the girl on the right is a tad distracting.', '2008-11-15 16:05:55.000000', NULL, 1),
(5065339, 737365, 54478, '<td valign="top">I like how the red makes your subject stand out. Nice capture.</td>', 'I like how the red makes your subject stand out. Nice capture.', '2008-11-15 16:06:12.000000', NULL, 1),
(5065341, 737378, 54478, '<td valign="top">Very nicee. I like how the grainy texture adds to the photo. The larger borders on the top and bottom are a tad distracting.</td>', 'Very nicee. I like how the grainy texture adds to the photo. The larger borders on the top and bottom are a tad distracting.', '2008-11-15 16:07:03.000000', NULL, 1),
(5065345, 738556, 54478, '<td valign="top">I think this photo would have turned out better if it was a clear day. If it were a clear day, the colors would have "popped".</td>', 'I think this photo would have turned out better if it was a clear day. If it were a clear day, the colors would have "popped".', '2008-11-15 16:07:54.000000', NULL, 1),
(5065351, 737771, 54478, '<td valign="top">Nice use of the color red, but the subject just isn''t exciting. I do like the background.</td>', 'Nice use of the color red, but the subject just isn''t exciting. I do like the background.', '2008-11-15 16:09:25.000000', NULL, 1),
(5065355, 738458, 54478, '<td valign="top">Good use of the color red. I wish the photo would have been a tad brighter.</td>', 'Good use of the color red. I wish the photo would have been a tad brighter.', '2008-11-15 16:09:46.000000', NULL, 1),
(5065358, 738103, 54478, '<td valign="top">Nice use of the color red, but some portions of the photo seen a little blown.</td>', 'Nice use of the color red, but some portions of the photo seen a little blown.', '2008-11-15 16:10:27.000000', NULL, 1),
(5065360, 737053, 54478, '<td valign="top">Interestin, I''ve never seen a red castle before The red portions of the castle almost seemed forced.</td>', 'Interestin, I''ve never seen a red castle before The red portions of the castle almost seemed forced.', '2008-11-15 16:10:59.000000', NULL, 1),
(5065365, 738042, 54478, '<td valign="top">Awesome simple photo. I wish person standing would have been standing ever so slightly to the right. I usually don''t like top and bottom borders, but in this photo it really adds to the composition. Great lighting as well.</td>', 'Awesome simple photo. I wish person standing would have been standing ever so slightly to the right. I usually don''t like top and bottom borders, but in this photo it really adds to the composition. Great lighting as well.', '2008-11-15 16:12:26.000000', NULL, 1),
(5065366, 738273, 43774, '<td valign="top">Wow, gorgeous! This has got to be the winner. I love your title too.</td>', 'Wow, gorgeous! This has got to be the winner. I love your title too.', '2008-11-15 16:12:29.000000', NULL, 1),
